import { errorMessage } from "./logic";
import { importedFileSource, relativeFilePath, type ChangeSet, type FileDiff, type FileSource, type WorkspaceDocument, type WorkspaceFile } from "./workspaceFiles";

export interface PreviewRequest { id: number; mode: "files" | "changes" | "conversation" | "history"; path?: string; paths?: string[]; receiptId?: string }
type DocumentState = { loading: boolean; error: string; document?: WorkspaceDocument };
type ViewMode = "preview" | "source" | "diff";
const emptyChanges: ChangeSet = { files: [], repository: false };
function FileIcon({ folder = false }: { folder?: boolean }) { return <svg viewBox="0 0 16 16" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.2" aria-hidden="true">{folder ? <path d="M1.5 4h5l1.5 1.5h6.5v8h-13V4Zm0 0V2.5h5L8 4" /> : <path d="M4 1.5h5l3.5 3.5v9.5H4v-13Zm5 0V5h3.5" />}</svg>; }

function BinaryPreview({ document }: { document: WorkspaceDocument }) {
  const [url, setUrl] = useState("");
  useEffect(() => {
    if (!document.bytes) { setUrl(""); return; }
    const owned = URL.createObjectURL(new Blob([new Uint8Array(document.bytes)], { type: document.mime || "application/octet-stream" }));
    setUrl(owned);
    return () => URL.revokeObjectURL(owned);
  }, [document]);
  if (!url) return <p className="preview-notice">此格式暂不支持预览。</p>;
  const filename = document.path.split("/").pop();
  return <div className="binary-preview"><div className="binary-toolbar"><span>{document.kind === "pdf" ? "PDF 文档" : "图片"} · {(document.size / 1024).toFixed(1)} KB</span><a href={url} download={filename}>下载{document.kind === "pdf" ? " PDF" : "图片"}</a></div>
    {document.kind === "pdf" ? navigator.pdfViewerEnabled === false ? <p className="preview-notice">当前查看器不支持内嵌 PDF。可下载后阅读。</p> : <object className="pdf-preview" data={`${url}#view=FitH&toolbar=1&navpanes=0`} type="application/pdf" aria-label={`${filename} PDF 预览`}><p className="preview-notice">无法显示 PDF，<a href={url} download={filename}>下载文件</a>后阅读。</p></object> : <div className="image-preview"><img src={url} alt={filename || "工作空间图片"} /></div>}
  </div>;
}

function DocumentPane({ state, path, mode, source, native, visible, refresh, onOpen }: { state: DocumentState; path: string; mode: ViewMode; source: FileSource | null; native: boolean; visible: boolean; refresh: number; onOpen: (path: string) => void }) {
  const [diff, setDiff] = useState<FileDiff | null>(null), [diffError, setDiffError] = useState("");
  const [diffLoading, setDiffLoading] = useState(false);
  useEffect(() => {
    if (mode !== "diff" || !source || !visible) return;
    let active = true; setDiffLoading(true); setDiffError("");
    void source.diff(path).then((value) => { if (active) setDiff(value); }).catch((problem) => { if (active) setDiffError(errorMessage(problem)); }).finally(() => { if (active) setDiffLoading(false); });
    return () => { active = false; };
  }, [mode, path, source, visible, refresh]);
  const document = state.document;
  return <div className="document-pane" hidden={!visible}>
    <div className="document-main" hidden={mode !== "diff"}>
      {diff?.scope === "staged" && <p className="preview-notice">暂存区更改 · 工作树与 HEAD 相同，以下显示暂存区相对 HEAD 的差异。</p>}
      {diffLoading && <p className="preview-notice" role="status">正在读取更改…</p>}{diffError && <p className="preview-notice error" role="alert">{diffError}</p>}
      {diff && <>{diff.truncated && <p className="preview-notice">更改内容过长，仅显示部分。</p>}{diff.binary ? <p className="preview-notice">二进制文件已更改，无法显示文本差异。</p> : diff.text ? <div className="document-source" hidden={!!diffError}><CodePreview text={diff.text} path={`${path}:diff`} diff /></div> : !diffLoading && <p className="preview-notice">没有可显示的文本差异。</p>}</>}
    </div>
    <div className="document-main" hidden={mode === "diff"}>
      {state.loading && <p className="preview-notice" role="status">正在读取文件…</p>}{state.error && <p className="preview-notice error" role="alert">{state.error}</p>}{document && <>
      {document.kind === "text" ? <><div className="document-rendered" hidden={mode === "source" || !/\.md(?:own)?$/i.test(path)}><FileMarkdown content={document.text || ""} path={path} native={native} onOpen={onOpen} /></div><div className="document-source" hidden={mode !== "source" && /\.md(?:own)?$/i.test(path)}><CodePreview text={document.text || ""} path={path} /></div></> : document.kind === "unsupported" ? <p className="preview-notice">此文件格式不支持预览（{document.size.toLocaleString()} 字节）。</p> : <BinaryPreview document={document} />}
    </>}</div>
  </div>;
}

function Directory({ path, source, active, onOpen, query, refresh, depth = 0 }: { path: string; source: FileSource; active: string; onOpen: (path: string) => void; query: string; refresh: number; depth?: number }) {
  const [entries, setEntries] = useState<WorkspaceFile[]>([]), [error, setError] = useState(""), [loading, setLoading] = useState(true);
  const [expanded, setExpanded] = useState(new Set<string>());
  useLayoutEffect(() => { setEntries([]); setError(""); setExpanded(new Set()); }, [path, source]);
  useEffect(() => { let current = true; setLoading(true); setError(""); void source.list(path).then((value) => { if (current) setEntries(value); }).catch((problem) => { if (current) { setError(errorMessage(problem)); setEntries([]); } }).finally(() => { if (current) setLoading(false); }); return () => { current = false; }; }, [path, source, refresh]);
  useEffect(() => { const branch = entries.find((entry) => entry.directory && active.startsWith(`${entry.path}/`)); if (branch) setExpanded((old) => old.has(branch.path) ? old : new Set([...old, branch.path])); }, [active, entries]);
  return <div className="file-directory">{loading && <p className="tree-notice" role="status">读取目录…</p>}{error && <p className="tree-notice error" role="alert">{error}</p>}{!loading && !error && !entries.length && <p className="tree-notice">空目录</p>}
    {entries.filter((entry) => !query || entry.directory || entry.path.toLocaleLowerCase().includes(query)).map((entry) => <div key={entry.path}>
      <button type="button" className={`file-tree-row${active === entry.path ? " selected" : ""}`} style={{ paddingInlineStart: 8 + depth * 14 }} aria-expanded={entry.directory ? expanded.has(entry.path) : undefined} aria-current={active === entry.path ? "true" : undefined} title={entry.path} onClick={() => entry.directory ? setExpanded((old) => { const next = new Set(old); if (next.has(entry.path)) next.delete(entry.path); else next.add(entry.path); return next; }) : onOpen(entry.path)}>
        <span className="file-tree-chevron" data-expanded={entry.directory && expanded.has(entry.path)}>{entry.directory ? "›" : ""}</span><FileIcon folder={entry.directory} /><span>{entry.name}</span>
      </button>{entry.directory && <div hidden={!expanded.has(entry.path)}>{expanded.has(entry.path) && <Directory path={entry.path} source={source} active={active} onOpen={onOpen} query={query} refresh={refresh} depth={depth + 1} />}</div>}
    </div>)}
  </div>;
}

export default function FilePreviewWorkspace({ native, source: nativeSource, identity, workspaceName, open, present, visible, request, connection, onRequest, onHistoryLoaded, onClose, onChanges }: {
  native: boolean; source: FileSource | null; identity: string; workspaceName: string; open: boolean; present: boolean; visible: boolean; request: PreviewRequest | null; connection: Connection | null; onRequest: (messageId: string) => boolean; onHistoryLoaded: (record: ArtifactDiff) => void; onClose: () => void; onChanges: (count: number | undefined) => void;
}) {
  const [imported, setImported] = useState<FileSource | null>(null), [importName, setImportName] = useState("");
  const source = nativeSource || imported;
  const [tabs, setTabs] = useState<string[]>([]), [active, setActive] = useState("");
  const [historyTabs, setHistoryTabs] = useState<Record<string, { receiptId: string; path: string }>>({});
  const [documents, setDocuments] = useState<Record<string, DocumentState>>({});
  const [modes, setModes] = useState<Record<string, ViewMode>>({}), [tree, setTree] = useState(true), [query, setQuery] = useState("");
  const [scope, setScope] = useState<PreviewRequest["mode"]>("files"), [paths, setPaths] = useState<string[]>([]);
  const [changes, setChanges] = useState<ChangeSet>(emptyChanges), [changesError, setChangesError] = useState(""), [refresh, setRefresh] = useState(0);
  const [feedback, setFeedback] = useState("");
  const filesInput = useRef<HTMLInputElement>(null), directoryInput = useRef<HTMLInputElement>(null), panel = useRef<HTMLElement>(null);
  const sourceRef = useRef(source), documentRef = useRef(documents), readSerial = useRef(new Map<string, number>()), lastRequest = useRef(0), feedbackTimer = useRef<number>();
  const nextReadId = useRef(0);
  const latestIdentity = useRef(identity);
  sourceRef.current = source; documentRef.current = documents;
  useLayoutEffect(() => { if (latestIdentity.current !== identity) { setImported(null); setImportName(""); latestIdentity.current = identity; } }, [identity]);
  useEffect(() => { directoryInput.current?.setAttribute("webkitdirectory", ""); return () => window.clearTimeout(feedbackTimer.current); }, []);
  const report = (message: string) => { setFeedback(message); window.clearTimeout(feedbackTimer.current); feedbackTimer.current = window.setTimeout(() => setFeedback(""), 2200); };
  useLayoutEffect(() => { setTabs([]); setHistoryTabs({}); setActive(""); setDocuments({}); setModes({}); readSerial.current.clear(); setChanges(emptyChanges); onChanges(undefined); }, [identity, source, onChanges]);
  const read = useCallback((path: string, force = false) => {
    if (!source || (!force && documentRef.current[path])) return;
    const serial = ++nextReadId.current; readSerial.current.set(path, serial);
    setDocuments((old) => ({ ...old, [path]: { loading: true, error: "", document: old[path]?.document } }));
    void source.read(path).then((document) => { if (sourceRef.current === source && readSerial.current.get(path) === serial) setDocuments((old) => ({ ...old, [path]: { loading: false, error: "", document } })); }).catch((problem) => { if (sourceRef.current === source && readSerial.current.get(path) === serial) setDocuments((old) => ({ ...old, [path]: { loading: false, error: errorMessage(problem) } })); });
  }, [source]);
  const openFile = useCallback((value: string) => { try { const path = relativeFilePath(value); setTabs((old) => old.includes(path) ? old : [...old, path]); setActive(path); read(path); } catch (problem) { report(errorMessage(problem)); } }, [read]);
  useEffect(() => {
    if (!request || request.id === lastRequest.current) return;
    lastRequest.current = request.id;
    if (request.mode === "history" && request.receiptId && request.path) {
      try {
        const path = relativeFilePath(request.path), key = `history:${request.receiptId}`;
        setHistoryTabs((old) => ({ ...old, [key]: { receiptId: request.receiptId!, path } }));
        setTabs((old) => old.includes(key) ? old : [...old, key]); setActive(key);
      } catch (problem) { report(errorMessage(problem)); }
    } else {
      setScope(request.mode); setPaths(request.paths || []); setTree(true);
      if (request.path) openFile(request.path);
    }
  }, [request, openFile]);
  useEffect(() => { if (source) tabs.filter((path) => !path.startsWith("history:")).forEach((path) => read(path)); }, [source, tabs, read]);
  useEffect(() => {
    if (!source || !open) return;
    let current = true, busy = false;
    const load = async () => { if (busy) return; busy = true; try { const result = await source.changes(); if (current) { setChanges(result); setChangesError(""); onChanges(result.repository ? result.files.length : undefined); } } catch (problem) { if (current) { setChanges(emptyChanges); setChangesError(errorMessage(problem)); onChanges(undefined); } } finally { busy = false; } };
    void load(); const timer = window.setInterval(() => void load(), 6000);
    return () => { current = false; window.clearInterval(timer); };
  }, [source, open, refresh, onChanges]);
  const chooseFiles = (input: FileList | null) => { if (!input?.length) return; const files = [...input]; setImported(importedFileSource(files)); setImportName(files[0].webkitRelativePath?.split("/")[0] || "已选择的文件"); setTabs([]); setDocuments({}); setActive(""); setScope("files"); };
  const closeTab = (path: string) => { const index = tabs.indexOf(path), next = tabs.filter((tab) => tab !== path); setTabs(next); if (active === path) setActive(next[Math.min(index, next.length - 1)] || ""); readSerial.current.delete(path); setDocuments((old) => { const copy = { ...old }; delete copy[path]; return copy; }); };
  const mode = modes[active] || "preview", document = documents[active]?.document;
  const activeHistory = historyTabs[active], activePath = activeHistory?.path || active;
  const tabPath = (key: string) => historyTabs[key]?.path || key;
  const tabName = (key: string) => `${tabPath(key).split("/").pop()}${historyTabs[key] ? " · 记录的更改" : ""}`;
  const changed = changes.files.find((file) => file.path === active);
  const displayedChanges = scope === "conversation" ? paths.map((path) => changes.files.find((file) => file.path === path) || { path, status: "记录" }) : changes.files;
  return <aside ref={panel} className={`file-preview-workspace${tree ? " with-file-tree" : ""}`} hidden={!present || !visible} aria-label="工作空间文件预览" onKeyDown={(event) => { if (event.key === "Escape" && !event.defaultPrevented && !(event.target instanceof HTMLInputElement)) { event.preventDefault(); onClose(); } }}>
    <div className="preview-tabs-bar"><div className="preview-tabs" role="tablist" aria-label="打开的文件">{tabs.map((path) => <div className={`preview-tab${active === path ? " active" : ""}`} key={path}><button type="button" role="tab" id={`file-tab-${tabs.indexOf(path)}`} aria-controls={`file-pane-${tabs.indexOf(path)}`} aria-selected={active === path} tabIndex={active === path ? 0 : -1} title={tabPath(path)} onClick={() => setActive(path)} onKeyDown={(event) => { const index = tabs.indexOf(path), next = event.key === "ArrowRight" ? (index + 1) % tabs.length : event.key === "ArrowLeft" ? (index + tabs.length - 1) % tabs.length : event.key === "Home" ? 0 : event.key === "End" ? tabs.length - 1 : -1; if (next >= 0) { event.preventDefault(); setActive(tabs[next]); requestAnimationFrame(() => panel.current?.querySelector<HTMLButtonElement>(`#file-tab-${next}`)?.focus()); } if (event.key === "Delete") closeTab(path); }}><FileIcon /><span>{tabName(path)}</span></button><button type="button" className="preview-tab-close" aria-label={`关闭 ${historyTabs[path] ? tabName(path) : path}`} onClick={() => closeTab(path)}>×</button></div>)}</div><button type="button" className="icon-button" aria-label="切换文件树" aria-pressed={tree} title="文件树" onClick={() => setTree((value) => !value)}><svg viewBox="0 0 20 20" width="18" height="18" fill="none" stroke="currentColor" strokeWidth="1.3" aria-hidden="true"><rect x="2.5" y="3" width="15" height="14" rx="3" /><path d="M12 3v14" /></svg></button><button type="button" className="icon-button preview-close" aria-label="关闭文件预览" title="关闭预览 · Escape" onClick={onClose}>×</button></div>
    <div className="preview-toolbar"><span className="preview-breadcrumb" title={activePath || workspaceName}>{source === imported ? importName : workspaceName}<span>›</span><strong>{activePath || "文件"}</strong></span>{activeHistory ? <button type="button" className="text-button" onClick={() => openFile(activeHistory.path)}>查看当前文件</button> : active && <div className="preview-view-actions">{changed && <button type="button" aria-pressed={mode === "diff"} onClick={() => setModes((old) => ({ ...old, [active]: mode === "diff" ? "preview" : "diff" }))}>显示更改</button>}{document?.kind === "text" && /\.md(?:own)?$/i.test(active) && <button type="button" aria-pressed={mode === "source"} onClick={() => setModes((old) => ({ ...old, [active]: mode === "source" ? "preview" : "source" }))}>{mode === "source" ? "预览" : "查看源代码"}</button>}{document?.text !== undefined && <button type="button" aria-label="复制文件内容" title="复制内容" onClick={() => void navigator.clipboard.writeText(document.text || "").then(() => report("已复制文件内容"), () => report("无法复制，请手动选择。"))}>复制</button>}<button type="button" aria-label="重新读取文件" title="重新读取" onClick={() => { read(active, true); setRefresh((value) => value + 1); }}>↻</button></div>}</div>
    {feedback && <span className="preview-feedback" role="status">{feedback}</span>}
    <div className="preview-content"><div className="preview-document">{tabs.map((path, index) => <div className="file-tab-panel" key={path} id={`file-pane-${index}`} role="tabpanel" aria-labelledby={`file-tab-${index}`} hidden={active !== path}>{historyTabs[path] ? <ArtifactHistoryPreview connection={connection} receiptId={historyTabs[path].receiptId} visible={active === path} onClose={() => closeTab(path)} onRequest={onRequest} onLoaded={onHistoryLoaded} /> : <DocumentPane state={documents[path] || { loading: !!source, error: source ? "" : "请先选择此文件所在的目录。" }} path={path} mode={modes[path] || "preview"} source={source} native={native} refresh={refresh} visible={active === path} onOpen={openFile} />}</div>)}{!active && <div className="preview-empty"><FileIcon folder /><h3>工作空间文件</h3><p>{source ? "从文件树选择文件，或点击对话中的文件引用。" : "在浏览器中选择本地目录或文件进行只读预览。"}</p>{!native && <div className="button-row"><button type="button" className="button" onClick={() => directoryInput.current?.click()}>选择目录</button><button type="button" className="button" onClick={() => filesInput.current?.click()}>选择文件</button></div>}</div>}</div>
      <div className="preview-file-tree" hidden={!tree}><div className="file-tree-search"><input aria-label="筛选已加载文件" placeholder="筛选已加载文件…" value={query} onChange={(event) => setQuery(event.target.value)} /></div><div className="file-tree-scopes"><button type="button" aria-pressed={scope === "files"} onClick={() => setScope("files")}>所有文件</button><button type="button" aria-pressed={scope === "changes"} onClick={() => setScope("changes")}>已更改{changes.repository ? ` ${changes.files.length}` : ""}</button>{scope === "conversation" && <span>对话记录</span>}<button type="button" aria-label="刷新文件树" title="刷新文件树与更改" onClick={() => setRefresh((value) => value + 1)}>↻</button></div><div className="file-tree-scroll">{scope === "files" ? source ? <Directory path="" source={source} active={active} onOpen={openFile} query={query.toLocaleLowerCase().trim()} refresh={refresh} /> : <p className="tree-notice">尚未选择文件。</p> : <>{changesError && <p className="tree-notice error" role="alert">{changesError}</p>}<p className="file-tree-caption">{scope === "conversation" ? "已加载对话中记录的文件；差异来自当前 Git。" : changes.repository ? "当前工作空间 · Git 工作树与暂存区" : "当前文件来源没有 Git 变更记录。"}</p>{displayedChanges.filter((file) => file.path.toLocaleLowerCase().includes(query.toLocaleLowerCase().trim())).map((file) => <button type="button" key={file.path} className={`file-tree-row changed-file${active === file.path ? " selected" : ""}`} title={file.path} onClick={() => { openFile(file.path); if (changes.files.some((change) => change.path === file.path)) setModes((old) => ({ ...old, [file.path]: "diff" })); }}><span className="file-change-status">{file.status}</span><span>{file.path}</span>{file.added !== undefined && <small className="file-added">+{file.added}</small>}{file.removed !== undefined && <small className="file-removed">−{file.removed}</small>}</button>)}{changes.truncated && <p className="tree-notice">变更较多，仅显示已读取部分。</p>}</>}</div>{!native && <button type="button" className="file-import-button" onClick={() => directoryInput.current?.click()}>选择本地目录…</button>}</div>
    </div><input ref={filesInput} type="file" multiple hidden aria-label="选择预览文件" onChange={(event) => { chooseFiles(event.target.files); event.currentTarget.value = ""; }} /><input ref={directoryInput} type="file" multiple hidden aria-label="选择预览目录" onChange={(event) => { chooseFiles(event.target.files); event.currentTarget.value = ""; }} />
  </aside>;
}

export function PreviewDivider({ width, onResize }: { width: number; onResize: (width: number) => void }) {
  const drag = useRef<{ x: number; width: number } | null>(null);
  const clamp = (value: number) => Math.min(76, Math.max(34, value));
  const move = (event: ReactPointerEvent<HTMLDivElement>) => { if (!drag.current) return; const total = event.currentTarget.parentElement?.clientWidth || 1; onResize(clamp(drag.current.width + (drag.current.x - event.clientX) / total * 100)); };
  return <div className="preview-divider" role="separator" aria-label="调整文件预览宽度" aria-orientation="vertical" aria-valuemin={34} aria-valuemax={76} aria-valuenow={Math.round(width)} tabIndex={0} onPointerDown={(event) => { drag.current = { x: event.clientX, width }; event.currentTarget.setPointerCapture(event.pointerId); }} onPointerMove={move} onPointerUp={(event) => { drag.current = null; event.currentTarget.releasePointerCapture(event.pointerId); }} onPointerCancel={() => { drag.current = null; }} onKeyDown={(event) => { if (["ArrowLeft", "ArrowRight", "Home", "End"].includes(event.key)) { event.preventDefault(); onResize(event.key === "Home" ? 34 : event.key === "End" ? 76 : clamp(width + (event.key === "ArrowLeft" ? 2 : -2))); } }} />;
}
.home-files-button:hover { color: var(--color-text); background: var(--color-background-secondary-ghost-hover); }
.preview-divider { position: relative; grid-column: 2; z-index: 2; width: 100%; margin: 0; cursor: col-resize; touch-action: none; background: var(--app-color-background-surface); }
.preview-divider::before { content: ""; position: absolute; inset: 0 2px; background: var(--color-border-subtle); transition: background-color .15s var(--ease-out); }
.preview-divider:hover::before, .preview-divider:focus-visible::before { background: var(--color-accent); }
.file-preview-workspace { position: relative; grid-column: 3; display: flex; flex-direction: column; min-height: 0; min-width: 0; overflow: hidden; background: var(--app-color-background-surface); opacity: var(--preview-progress,0); transform: translateX(calc((1 - var(--preview-progress,0))*6px)); }
.preview-tabs-bar { display: flex; align-items: center; gap: 4px; min-height: 52px; padding: 6px 10px; border-bottom: 1px solid var(--color-border-subtle); }
.preview-tabs { display: flex; flex: 1; min-width: 0; overflow: auto; gap: 6px; }
.preview-tab { display: flex; align-items: center; flex: 0 0 auto; max-width: 260px; height: 32px; border: .8px solid transparent; border-radius: 10px; color: var(--muted); }
.preview-tab.active { border-color: var(--color-border); color: var(--color-text); box-shadow: var(--shadow-sm); }
.preview-tab:hover { background: var(--color-background-control-subtle); }
.preview-tab > [role="tab"] { display: flex; align-items: center; gap: 7px; min-width: 0; height: 30px; padding: 0 8px 0 10px; border: 0; border-radius: 8px; background: none; font-size: 12px; }
.preview-tab > [role="tab"] > span { min-width: 0; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }
.preview-tab > [role="tab"] > svg { flex: none; }
.preview-tab-close { display: grid; place-items: center; width: 24px; height: 24px; flex: none; margin-right: 3px; padding: 0; border: 0; border-radius: 7.5px; background: none; color: var(--muted); font-size: 16px; }
.preview-tab-close:hover { background: var(--color-background-secondary-ghost-hover); color: var(--color-text); }
.preview-tabs-bar > .icon-button { flex: none; width: 28px; height: 28px; }
.preview-close { font-size: 20px; }
.preview-toolbar { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; min-height: 44px; padding: 7px 12px; border-bottom: 1px solid var(--color-border-subtle); }
.preview-breadcrumb { display: flex; align-items: center; gap: 8px; min-width: 0; flex: 1 1 100px; color: var(--muted); font-size: 12px; white-space: nowrap; }
.preview-breadcrumb > strong { min-width: 0; overflow: hidden; text-overflow: ellipsis; font-weight: 500; color: var(--color-text); }
.preview-view-actions { display: flex; align-items: center; gap: 5px; margin-left: auto; }
.preview-view-actions button { min-height: 28px; padding: 3px 9px; border: .8px solid var(--color-border); border-radius: 999px; background: var(--app-color-background-surface); font-size: 12px; line-height: 20px; white-space: nowrap; }
.preview-view-actions button:hover, .preview-view-actions button[aria-pressed="true"] { background: var(--color-background-secondary-ghost-hover); }
.preview-content { display: grid; grid-template-columns: minmax(0,1fr); flex: 1; min-width: 0; min-height: 0; }
