  const go = (direction: number) => { if (!matches.length) return; const next = searchNavigated.current ? match + direction : direction < 0 ? -1 : 0; const index = (next + matches.length) % matches.length; searchNavigated.current = true; setMatch(index); if (viewport.current) { if (wrap) viewport.current.querySelector(`[data-line="${matches[index] + 1}"]`)?.scrollIntoView({ block: "center" }); else viewport.current.scrollTop = Math.max(0, (matches[index] - 8) * lineHeight); } };
  return <div className={`code-preview${compact ? " code-preview-compact" : ""}${diff ? " code-preview-diff" : ""}`}>
    {!compact && <div className="source-controls"><label><svg viewBox="0 0 16 16" width="14" height="14" aria-hidden="true" fill="none" stroke="currentColor"><circle cx="7" cy="7" r="4.5" /><path d="m10.5 10.5 3 3" /></svg><input aria-label="在文件中查找" placeholder="在文件中查找" value={query} onChange={(event) => updateQuery(event.target.value)} onKeyDown={(event) => { if (event.key === "Enter") { event.preventDefault(); go(event.shiftKey ? -1 : 1); } if (event.key === "Escape") updateQuery(""); }} /></label>{query && <><span>{matches.length ? match + 1 : 0}/{matches.length}</span><button type="button" aria-label="上一个匹配" disabled={!matches.length} onClick={() => go(-1)}>↑</button><button type="button" aria-label="下一个匹配" disabled={!matches.length} onClick={() => go(1)}>↓</button></>}<button type="button" className={wrap ? "active" : ""} disabled={!allowWrap} title={allowWrap ? undefined : "超过 5,000 行的文件使用虚拟滚动，请横向阅读。"} aria-pressed={wrap} onClick={() => setWrap((value) => !value)}>自动换行</button><span>{lines.length.toLocaleString()} 行</span></div>}
