      <div style={{ paddingTop: start * lineHeight, paddingBottom: (lines.length - end) * lineHeight }}>
        {lines.slice(start, end).map((line, offset) => { const number = start + offset, row = rows[number]; return <div className={`source-line${query && line.toLocaleLowerCase().includes(query.toLocaleLowerCase()) ? " search-match" : ""}${diff ? ` diff-${row.kind}` : ""}`} data-line={number + 1} data-old-line={diff ? row.oldLine : undefined} data-new-line={diff ? row.newLine : undefined} key={number}><span className="source-line-number" aria-hidden="true">{diff ? row.newLine ?? row.oldLine ?? "" : number + 1}</span><code><Tokens line={(diff ? row.content : line) || " "} /></code></div>; })}
